// Real brand marks for the /compare pages, the homepage migration strip, the
// "replaced tools" hero banner, and the architecture diagram. Sources: Simple
// Icons (CC0) for Vercel, Netlify, Coolify, Railway, Render, Fly.io,
// Cloudflare Pages, CapRover, Portainer, Kubernetes, Docker, PostgreSQL,
// MongoDB, MariaDB, Redis, Scaleway, Sentry, PostHog, Pingdom, Resend,
// Datadog, OpenTelemetry, Claude, JavaScript, Python, Go, PHP, Ruby, .NET,
// Node.js, Google Gemini, Plausible Analytics and SendGrid; Devicon for
// Heroku; official project assets for Dokploy, Kamal, Dokku (docs/assets/
// dokku-logo.svg), FullStory (favicon.svg) and LogRocket (favicon.svg);
// @lobehub/icons-static-svg (MIT) for OpenAI and xAI, which Simple Icons
// doesn't list (trademark policy). AWS, Java, and E2B still have no available
// real mark, so pages needing them use a generic icon instead. Dark marks use
// currentColor so they adapt to dark mode.
//
// Two notes on the marks taken from favicons. FullStory's wraps its single
// path in a full-bleed rect mask purely to clip the starburst arms, which
// extend past the viewBox; an outer <svg> already clips to its viewport, so
// that mask is dropped here rather than reproduced. Dokku's is the only mark
// in this file that needs internal ids (two alpha masks for the shading), so
// they are namespaced "dokku-0"/"dokku-1" — safe because a given logo renders
// at most once per page. If a logo ever renders twice on one page, those ids
// collide and the masks break, so give it unique ids at that point.

export function PlatformLogo({
  name,
  className,
}: {
  name: string;
  className?: string;
}) {
  const logo = logos[name];
  if (!logo) return null;
  return logo(className);
}

